package lk.ac.sliit.ridelink.ride.infrastructure.client.account;
import lk.ac.sliit.ridelink.ride.application.dto.response.AccountValidationData; import lk.ac.sliit.ridelink.ride.application.port.out.AccountValidationPort; import lk.ac.sliit.ridelink.ride.application.usecase.ExternalServiceException; import lk.ac.sliit.ridelink.ride.infrastructure.client.ClientSupport; import lk.ac.sliit.ridelink.ride.infrastructure.security.InternalServiceTokenProvider; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.util.UUID;
@Component public class AccountServiceClient implements AccountValidationPort {private final RestClient client;private final InternalServiceTokenProvider tokens;public AccountServiceClient(@Qualifier("accountRestClient") RestClient client,InternalServiceTokenProvider tokens){this.client=client;this.tokens=tokens;}public AccountValidationData validate(UUID id,String role){try{return client.get().uri(u->u.path("/api/v1/internal/accounts/{id}/validation").queryParam("requiredRole",role).build(id)).header(HttpHeaders.AUTHORIZATION,"Bearer "+tokens.token()).retrieve().onStatus(HttpStatusCode::isError,(q,r)->ClientSupport.status("Account Service",r.getStatusCode())).body(AccountValidationData.class);}catch(ExternalServiceException e){throw e;}catch(RestClientException e){throw ClientSupport.failure("Account Service",e);}}}
